/**
 * src/agents/tx-4-imp-1/prompts/action-05.ts
 *
 * Action 5: 優先度順に整理した朝会資料を自動生成
 * tx-4-imp-1 Agent の第5ステップ
 * 抽出・優先度付けされた課題から朝会報告用資料を生成
 */

export const ACTION_05_PROMPT_VERSION = "1.0.0";

export interface Action05PromptInput {
  prioritizedIssues: Array<{
    id: string;
    title: string;
    description: string;
    priority: "critical" | "high" | "medium" | "low";
    severity: number;
    urgency: number;
    category: string;
    affectedTeams: string[];
    recommendedAction: string;
    estimatedImpact: string;
  }>;
  reportDate: string;
  departmentName: string;
  meetingTime: string;
  previousUnresolvedIssues: Array<{
    id: string;
    title: string;
    status: string;
    daysOpen: number;
  }>;
  teamMetrics: {
    totalReports: number;
    issueCount: number;
    criticalCount: number;
    resolutionRate: number;
  };
}

export interface Action05PromptOutput {
  materialTitle: string;
  executiveSummary: string;
  sections: Array<{
    sectionTitle: string;
    content: string;
    issueIds: string[];
    priority: string;
  }>;
  criticalAlerts: Array<{
    issueId: string;
    title: string;
    action: string;
    owner: string;
  }>;
  discussionPoints: string[];
  followUpActions: Array<{
    action: string;
    owner: string;
    dueDate: string;
    priority: string;
  }>;
  attachments: Array<{
    name: string;
    type: string;
    content: string;
  }>;
  generatedAt: string;
  estimatedMeetingDuration: number;
}

export function buildAction05Prompt(input: Action05PromptInput): string {
  const criticalIssues = input.prioritizedIssues.filter(
    (issue) => issue.priority === "critical"
  );
  const highIssues = input.prioritizedIssues.filter(
    (issue) => issue.priority === "high"
  );
  const mediumIssues = input.prioritizedIssues.filter(
    (issue) => issue.priority === "medium"
  );

  const issuesByCategory = input.prioritizedIssues.reduce(
    (acc, issue) => {
      if (!acc[issue.category]) {
        acc[issue.category] = [];
      }
      acc[issue.category].push(issue);
      return acc;
    },
    {} as Record<string, typeof input.prioritizedIssues>
  );

  const unresolved = input.previousUnresolvedIssues
    .sort((a, b) => b.daysOpen - a.daysOpen)
    .slice(0, 5);

  const prompt = `
# 朝会報告資料自動生成プロンプト

## 目的
優先度付けされた課題データから、部長が朝会で使用する報告資料を自動生成する。
資料は以下の要件を満たす必要がある：
- 経営層・チームメンバーの両者が理解できる内容
- 優先度の高い課題から順に配置
- 具体的な対応方針と責任者を明記
- 朝会での議論時間を効率化する構成

## 入力データ

### 報告日時
- 報告日: ${input.reportDate}
- 朝会時間: ${input.meetingTime}
- 部門: ${input.departmentName}

### 課題サマリー
- 総課題数: ${input.prioritizedIssues.length}
- 緊急課題: ${criticalIssues.length}
- 高優先度: ${highIssues.length}
- 中優先度: ${mediumIssues.length}

### チームメトリクス
- 日報提出数: ${input.teamMetrics.totalReports}
- 報告課題数: ${input.teamMetrics.issueCount}
- 緊急課題数: ${input.teamMetrics.criticalCount}
- 解決率: ${(input.teamMetrics.resolutionRate * 100).toFixed(1)}%

### 未解決課題（継続追跡）
${unresolved.map((issue) => `- ${issue.title} (${issue.daysOpen}日経過, 状態: ${issue.status})`).join("\n")}

### 優先度別課題一覧

#### 緊急課題（即座の対応が必要）
${criticalIssues
  .map(
    (issue) => `
- **${issue.title}** (ID: ${issue.id})
  - 説明: ${issue.description}
  - 影響範囲: ${issue.affectedTeams.join(", ")}
  - 推奨対応: ${issue.recommendedAction}
  - 想定影響: ${issue.estimatedImpact}
`
  )
  .join("\n")}

#### 高優先度課題（本日中の対応開始が必要）
${highIssues
  .map(
    (issue) => `
- **${issue.title}** (ID: ${issue.id})
  - 説明: ${issue.description}
  - 影響範囲: ${issue.affectedTeams.join(", ")}
`
  )
  .join("\n")}

### カテゴリ別分類
${Object.entries(issuesByCategory)
  .map(
    ([category, issues]) => `
**${category}**: ${issues.length}件
${issues.map((issue) => `  - ${issue.title} (優先度: ${issue.priority})`).join("\n")}
`
  )
  .join("\n")}

## 生成要件

### 資料構成
1. **エグゼクティブサマリー**
   - 本日の重要ポイント（3-5項目）
   - 緊急対応が必要な課題の概要
   - 前日からの進捗状況

2. **セクション別構成**
   - 緊急課題セクション（詳細説明と対応方針）
   - 高優先度課題セクション（背景と対応計画）
   - 継続追跡課題セクション（進捗状況）
   - カテゴリ別課題セクション（傾向分析）

3. **クリティカルアラート**
   - 即座の判断・指示が必要な課題
   - 各課題の責任者と期限

4. **ディスカッションポイント**
   - 朝会で議論すべき項目
   - 意思決定が必要な事項

5. **フォローアップアクション**
   - 本日中に実施すべき対応
   - 責任者と期限の明記

### 資料品質基準
- 簡潔性: 各課題は3行以内で説明
- 明確性: 対応方針は具体的で実行可能
- 優先度: 重要度順に配置
- 実行性: 責任者と期限が明記されている

## 出力形式

JSON形式で以下の構造を返す：

\`\`\`json
{
  "materialTitle": "朝会報告資料 - YYYY年MM月DD日",
  "executiveSummary": "本日の重要ポイント...",
  "sections": [
    {
      "sectionTitle": "セクション名",
      "content": "セクション内容",
      "issueIds": ["issue-id-1", "issue-id-2"],
      "priority": "critical|high|medium"
    }
  ],
  "criticalAlerts": [
    {
      "issueId": "issue-id",
      "title": "課題タイトル",
      "action": "必要な対応",
      "owner": "責任者名"
    }
  ],
  "discussionPoints": ["議論ポイント1", "議論ポイント2"],
  "followUpActions": [
    {
      "action": "対応内容",
      "owner": "責任者",
      "dueDate": "YYYY-MM-DD HH:mm",
      "priority": "critical|high|medium"
    }
  ],
  "attachments": [
    {
      "name": "ファイル名",
      "type": "csv|chart|summary",
      "content": "ファイル内容またはURL"
    }
  ],
  "generatedAt": "ISO8601形式の生成時刻",
  "estimatedMeetingDuration": 15
}
\`\`\`

## 注意事項
- 資料は部長が朝会で即座に使用できる状態で生成すること
- 機密情報は適切にマスキングすること
- 課題の重複記載を避けること
- 前日の未解決課題の進捗を明記すること
`;

  return prompt;
}
